-- ============================================================================
-- seed_etl_run_config_CRE.sql  (CRE step-driver package)
--
-- Seeds COMMON.ETL_RUN_CONFIG_TBL for workflow wf_CRE_Stage_Load_Ongoing:
-- one row per driver row (STEP_NO = 0, IS_DRIVER = 'Y') + every transform
-- step + every publish branch. All IS_RUN_ENABLED = 'Y' (everything runs).
-- The DELETE below removes CRE rows for this workflow only, so re-running
-- this seed is safe. Run it in the COMMON schema (MDM_ETL_COMMON.COMMON).
-- NOTE: IS_DEPENDENT / DEPENDENT_ON / WORK_TABLES_PRODUCED are
-- informational for a driver run -- gating is by IS_RUN_ENABLED only.
-- The operator ONLY toggles IS_RUN_ENABLED; the driver does NOT validate
-- flag consistency.
-- 24 rows: 1 driver row + 5 steps + 18 publish branches.
-- ============================================================================

DELETE FROM ETL_RUN_CONFIG_TBL WHERE WORKFLOW_NAME = 'wf_CRE_Stage_Load_Ongoing';


-- 24 rows: 1 driver row + 5 steps + 18 publish branches.
